{
  "passageId": "corporate-law",
  "items": [
    {
      "slot": 1,
      "stem": "윗글의 내용에 대한 이해로 적절하지 않은 것은?",
      "stemPolarity": "SELECT_INCORRECT",
      "choices": [
        {
          "number": 1,
          "text": "법인은 자신의 이름으로 권리와 의무의 주체가 되므로, 개인의 출자로 형성된 자산도 그 소유권은 출자자 개인이 아닌 법인에게 귀속된다."
        },
        {
          "number": 2,
          "text": "재단 법인이 목적 사업 수행을 위한 기본 재산을 처분하거나 용도를 변경하여 그 액수를 줄이려면 반드시 관할 기관의 허가를 받아야 한다."
        },
        {
          "number": 3,
          "text": "정관이나 법령에 의해 자산 운용의 권한을 부여받은 사람이라도 정해진 절차에 어긋나거나 법인의 목적과 다르게 자산을 운용하면 처벌받을 수 있다."
        },
        {
          "number": 4,
          "text": "주식회사와 같이 경제적 이익을 목적으로 하는 법인은 법인의 종류와 자산 운용의 원칙을 정한 민법의 적용은 받지만 상법의 적용은 받지 않는다."
        },
        {
          "number": 5,
          "text": "주식회사가 주주들에게 이익을 분배하는 배당은 주주의 만족도를 높일 수 있으며, 회사는 이를 통해 추가적인 투자가 이루어질 것을 기대할 수 있다."
        }
      ],
      "answer": 4
    },
    {
      "slot": 2,
      "stem": "윗글의 재단 법인에 대한 이해로 적절한 것은?",
      "stemPolarity": "SELECT_CORRECT",
      "choices": [
        {
          "number": 1,
          "text": "재단 법인의 이사회는 행위 능력이 없는 법인을 대신하여 행위 능력을 행사하므로, 주요 사항에 대해서도 관할 기관의 허가 없이 결정권을 행사할 수 있다."
        },
        {
          "number": 2,
          "text": "재단 법인의 목적 사업 수행을 위한 기본 재산은 재단을 설립할 때가 아니라 설립 후 그 재산을 처분하려는 때에 이르러서야 정관에 기재해 등기해야 한다."
        },
        {
          "number": 3,
          "text": "재산과 단체 중 법인격의 부여 대상을 기준으로 법인을 구분할 때, 장학 재단은 자산 자체에 법인격이 부여되는 재단 법인에 해당한다."
        },
        {
          "number": 4,
          "text": "재단 법인이 기본 재산 외의 자산을 활용하여 수익을 추구하는 것은 출자자 개인에게 경제적 이익을 분배하기 위한 재원을 마련하려는 것이다."
        },
        {
          "number": 5,
          "text": "재단 법인은 기본 재산 외의 자산으로 일정 범위 안에서 수익을 추구해야 하지만, 그 자산을 운용한 실적을 관할 기관에 보고할 필요는 없다."
        }
      ],
      "answer": 3
    },
    {
      "slot": 3,
      "stem": "윗글의 자본금에 대한 이해로 적절하지 않은 것은?",
      "stemPolarity": "SELECT_INCORRECT",
      "choices": [
        {
          "number": 1,
          "text": "자본금은 주식회사가 주식을 발행하는 방식으로 조달한 자금에 해당한다."
        },
        {
          "number": 2,
          "text": "자본금의 금액은 발행된 총 주식 수에 주식의 시장 가격을 곱하여 산정한다."
        },
        {
          "number": 3,
          "text": "자본금은 원칙적으로 감액이 금지되지만, 누적 적자를 이익 잉여금이나 자본 잉여금으로도 보전할 수 없으면 사용하게 된다."
        },
        {
          "number": 4,
          "text": "자본금은 회사의 지급 능력을 보장하고 재무 안정성을 뒷받침하는 기초 자산에 해당한다."
        },
        {
          "number": 5,
          "text": "누적 적자를 이익 잉여금이나 자본 잉여금으로도 보전할 수 없어 자본금을 사용할 때, 그 감소는 회사의 존립을 위태롭게 한다."
        }
      ],
      "answer": 2
    }
  ]
}

